let lang='es',filter='all';
try{lang=localStorage.getItem('language')==='en'?'en':'es'}catch(e){}
const $=s=>document.querySelector(s);
function renderStores(){const query=$('#search').value.trim().toLocaleLowerCase();const visible=stores.map((s,i)=>({s,i})).filter(({s})=>(filter==='all'||s[2]===filter)&&s[0].toLocaleLowerCase().includes(query));$('#store-list').replaceChildren(...visible.map(({s,i})=>{const a=document.createElement('a');a.className='store-row';a.href=s[1];a.target='_blank';a.rel='noopener noreferrer';a.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><span class="store-name">${s[0]}</span><span class="store-category">${copy[lang][s[2]]}</span><span class="arrow" aria-hidden="true">↗</span>`;return a}));$('#empty').hidden=visible.length!==0;$('#results').textContent=copy[lang].results(visible.length)}
function renderFilters(){$('#filters').replaceChildren(...['all','fashion','home','food','pets','lifestyle'].map(key=>{const b=document.createElement('button');b.className='filter'+(filter===key?' active':'');b.textContent=copy[lang][key];b.setAttribute('aria-pressed',String(filter===key));b.onclick=()=>{filter=key;renderFilters();renderStores()};return b}));$('#filters').setAttribute('aria-label',lang==='es'?'Filtrar proyectos':'Filter projects')}
function renderFeatured(){const projects=[{i:0,img:'reza',label:'REZA'},{i:1,img:'hurom',label:'HUROM'},{i:2,img:'gitman',label:'GITMAN'},{i:10,img:'oishii',label:'Oishii'}];$('#featured').replaceChildren(...projects.map((p,n)=>{const s=stores[p.i];const a=document.createElement('a');a.className='project';a.href=s[1];a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',`${lang==='es'?'Visitar':'Visit'} ${s[0]} (${lang==='es'?'nueva pestaña':'new tab'})`);a.innerHTML=`<div class="project-image"><img src="assets/${p.img}.jpg" alt="${s[0]}" loading="lazy"><span class="image-label">${p.label}</span><span class="corner" aria-hidden="true">↗</span></div><div class="project-meta"><h3><small class="project-index">0${n+1}</small>${s[0]}</h3><span>${copy[lang][s[2]]} / Shopify</span></div>`;a.querySelector('img').onerror=e=>{e.target.style.display='none';a.querySelector('.image-label').style.display='flex'};return a}))}
function themeLabel(){$('#theme').setAttribute('aria-label',copy[lang][document.documentElement.dataset.theme==='dark'?'light':'dark']);$('#theme').setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));document.querySelector('meta[name="theme-color"]').content=document.documentElement.dataset.theme==='dark'?'#191d18':'#f4f3ee'}
function renderLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{el.innerHTML=copy[lang][el.dataset.i]});$('#language').innerHTML=(lang==='es'?'EN':'ES')+' <span>↗</span>';$('#language').setAttribute('aria-label',lang==='es'?'Switch to English':'Cambiar a español');$('#search').placeholder=copy[lang].search;$('#search').setAttribute('aria-label',copy[lang].search);document.querySelector('meta[name="description"]').content=lang==='es'?'Alberto Lopez Bastos — Desarrollador frontend Shopify. Liquid, themes a medida y experiencias de ecommerce.':'Alberto Lopez Bastos — Shopify Frontend Developer. Liquid, custom themes and ecommerce experiences.';renderFilters();renderFeatured();renderStores();themeLabel()}
$('#language').onclick=()=>{lang=lang==='es'?'en':'es';try{localStorage.setItem('language',lang)}catch(e){}renderLanguage()};$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('theme',theme)}catch(e){}themeLabel()};$('#search').addEventListener('input',renderStores);$('#year').textContent=new Date().getFullYear();renderLanguage();
